public:
    vector<int> permute(int n, long long k) {
        vector<int> odds, evens;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1) odds.push_back(i);
            else evens.push_back(i);
        }

        long long totalOddStart = countWays(odds.size(), evens.size());
        long long totalEvenStart = countWays(evens.size(), odds.size());
        if (k > totalOddStart + totalEvenStart) return {};

        vector<int> ans;
        int lastParity = -1;

        for (int step = 0; step < n; step++) {
            vector<int> candidates;
            if (lastParity != 1) candidates.insert(candidates.end(), odds.begin(), odds.end());
            if (lastParity != 0) candidates.insert(candidates.end(), evens.begin(), evens.end());
            sort(candidates.begin(), candidates.end());

            bool placed = false;
            for (int c : candidates) {
                int cParity = c % 2;
                long long ways = (cParity == 1) ? countWays(evens.size(), odds.size() - 1)
                                                : countWays(odds.size(), evens.size() - 1);
                if (k <= ways) {
                    ans.push_back(c);
                    if (cParity == 1) {
                        odds.erase(find(odds.begin(), odds.end(), c));
                    } else {
                        evens.erase(find(evens.begin(), evens.end(), c));
                    }
                    lastParity = cParity;
                    placed = true;
                    break;
                } else {
                    k -= ways;
                }
            }
            if (!placed) return {};
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    private long countWays(int numNeed, int numOther) {
        if (numNeed != numOther && numNeed != numOther + 1) return 0;
        final long INF = (long) 2e18;
        long res = 1;
        for (int i = 1; i <= numNeed; i++) {
            if (res > INF / i) return INF;
            res *= i;
        }
        for (int i = 1; i <= numOther; i++) {
            if (res > INF / i) return INF;
            res *= i;
        }
        return res;
    }

    public int[] permute(int n, long k) {
        List<Integer> odds = new ArrayList<>();
        List<Integer> evens = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1) odds.add(i);
            else evens.add(i);
        }

        long totalOddStart = countWays(odds.size(), evens.size());
        long totalEvenStart = countWays(evens.size(), odds.size());
        if (k > totalOddStart + totalEvenStart) return new int[0];

        int[] ans = new int[n];
        int lastParity = -1;

        for (int step = 0; step < n; step++) {
            List<Integer> candidates = new ArrayList<>();
            if (lastParity != 1) candidates.addAll(odds);
            if (lastParity != 0) candidates.addAll(evens);
            Collections.sort(candidates);

            boolean placed = false;
            for (int c : candidates) {
                int cParity = c % 2;
                long ways = (cParity == 1) ? countWays(evens.size(), odds.size() - 1)
                                           : countWays(odds.size(), evens.size() - 1);
                if (k <= ways) {
                    ans[step] = c;
                    if (cParity == 1) {
                        odds.remove(Integer.valueOf(c));
                    } else {
                        evens.remove(Integer.valueOf(c));
                    }
                    lastParity = cParity;
                    placed = true;
                    break;
                } else {
                    k -= ways;
                }
            }
            if (!placed) return new int[0];
        }
        return ans;
    }
}

