var permute = function(n, k) {
    let kBig = BigInt(k);
    const odds = [];
    const evens = [];
    for (let i = 1; i <= n; i++) {
        if (i % 2 === 1) odds.push(i);
        else evens.push(i);
    }

    function countWays(numNeed, numOther) {
        if (numNeed !== numOther && numNeed !== numOther + 1) return 0n;
        let res = 1n;
        for (let i = 1; i <= numNeed; i++) res *= BigInt(i);
        for (let i = 1; i <= numOther; i++) res *= BigInt(i);
        return res;
    }

    const totalOdd = countWays(odds.length, evens.length);
    const totalEven = countWays(evens.length, odds.length);
    if (kBig > totalOdd + totalEven) return [];

    const ans = [];
    let lastParity = -1;

    for (let step = 0; step < n; step++) {
        const candidates = [];
        if (lastParity !== 1) candidates.push(...odds);
        if (lastParity !== 0) candidates.push(...evens);
        candidates.sort((a, b) => a - b);

        let placed = false;
        for (const c of candidates) {
            const cParity = c % 2;
            const ways = (cParity === 1) ? countWays(evens.length, odds.length - 1)
                                         : countWays(odds.length, evens.length - 1);
            if (kBig <= ways) {
                ans.push(c);
                if (cParity === 1) {
                    odds.splice(odds.indexOf(c), 1);
                } else {
                    evens.splice(evens.indexOf(c), 1);
                }
                lastParity = cParity;
                placed = true;
                break;
            } else {
                kBig -= ways;
            }
        }
        if (!placed) return [];
    }
    return ans;
};
